add_filter( 'woocommerce_format_stock_quantity', 'perfectpixel_stock_quantity_unit', 10, 2 );

function perfectpixel_stock_quantity_unit( $quantity, $product ) {
	$categories = wp_parse_id_list( '{{stock_unit_category_ids}}' );
	$id         = $product->get_parent_id() ? $product->get_parent_id() : $product->get_id();
	if ( $categories && ! has_term( $categories, 'product_cat', $id ) ) {
		return $quantity;
	}
	return $quantity . ' ' . esc_html( '{{stock_unit_text}}' );
}
